<script setup lang="ts">
import {ElButton, ElInput, ElSelect, ElOption, ElTable, ElTableColumn} from 'element-plus'
import {computed,ref,watch} from 'vue'
import {api,type Account} from '../../api'
import {confirmAction} from '../../shared/confirm'
import {base,reasonText,money,incomeLabel,withdrawalLabel,type Restaurant,type PageResult,type DiningAccount,type DiningWithdrawal} from './types'
import './dining.css'
const props=defineProps<{account:Account}>(),canManage=computed(()=>props.account.permissionCodes.includes('dining.finance.manage'))
const restaurants=ref<Restaurant[]>([]),restaurantId=ref(''),detail=ref<DiningAccount|null>(null),loading=ref(false),busy=ref(''),error=ref(''),notice=ref(''),reasons=ref<Record<string,string>>({})
let generation=0
async function loadRestaurants(){error.value='';try{restaurants.value=(await api<PageResult<Restaurant>>(`${base}/restaurants?pageSize=100`)).items;if(!restaurantId.value&&restaurants.value.length)restaurantId.value=restaurants.value[0]!.id}catch(e){error.value=reasonText(e)}}
async function load(){const current=++generation;detail.value=null;if(!restaurantId.value)return;loading.value=true;error.value='';try{const result=await api<DiningAccount>(`${base}/restaurants/${restaurantId.value}/account`);if(current===generation)detail.value=result}catch(e){if(current===generation)error.value=reasonText(e)}finally{if(current===generation)loading.value=false}}
async function review(row:DiningWithdrawal,action:'approve'|'reject'){if(busy.value||!canManage.value||row.status!=='PENDING')return;const reason=reasons.value[row.id]?.trim()||'';if(action==='reject'&&!reason){error.value='驳回时请填写原因。';return}if(!await confirmAction(`确定${action==='approve'?'通过':'驳回'}这笔 ${money(row.amountFen)} 提现申请？审核通过仅记录审核结果，款项仍待打款。`))return;busy.value=row.id;error.value='';notice.value='';const target=restaurantId.value,current=generation;try{await api(`${base}/restaurants/${target}/withdrawals/${row.id}/${action}`,{method:'POST',body:JSON.stringify({revision:row.revision,reason})});if(current===generation){await load();notice.value='提现审核结果已保存。'}}catch(e){if(current===generation)error.value=`${reasonText(e)}；审核说明已保留，请刷新状态后再操作。`}finally{busy.value=''}}
watch(restaurantId,load)
watch(()=>props.account.accountId,()=>{generation++;detail.value=null;restaurantId.value='';loadRestaurants()},{immediate:true})
</script>
<template><section class="page-content dining-page"><header class="page-heading"><div><h1>餐饮佣金与提现</h1><p>餐饮佣金由履约前置仓利润份额承担。订单完成且过售后期后才可提现；审核通过不代表已打款。</p></div></header><section class="panel"><div class="toolbar"><label>餐饮店 <el-select v-model="restaurantId" aria-label="餐饮店" :disabled="!!busy" style="width:280px" placeholder="选择餐饮店"><el-option v-for="r in restaurants" :key="r.id" :value="r.id" :label="r.name"/></el-select></label><el-button :loading="loading" :disabled="!!busy" @click="restaurantId?load():loadRestaurants()">刷新</el-button></div><p v-if="error" class="error" role="alert">{{error}} <el-button @click="restaurantId?load():loadRestaurants()">重试</el-button></p><p v-if="notice" role="status">{{notice}}</p><p v-if="loading" role="status">正在读取佣金账户…</p><p v-if="!loading&&!restaurants.length&&!error">暂无餐饮店。</p><template v-if="detail"><p v-if="detail.fundingLabel">{{detail.fundingLabel}}</p><div class="balance"><div>可申请提现<strong>{{money(detail.availableFen)}}</strong></div><div>待满足条件<strong>{{money(detail.pendingFen)}}</strong></div><div>待核对<strong>{{money(detail.heldFen)}}</strong></div><div>提现占用<strong>{{money(detail.frozenFen)}}</strong></div></div><h2>提现申请</h2><el-table :data="detail.withdrawals" empty-text="暂无提现申请"><el-table-column label="金额" width="120"><template #default="{row}">{{money(row.amountFen)}}</template></el-table-column><el-table-column label="状态" min-width="150"><template #default="{row}">{{withdrawalLabel(row.status)}}</template></el-table-column><el-table-column prop="createdAt" label="申请时间" min-width="190"/><el-table-column prop="reason" label="审核说明" min-width="180"/><el-table-column v-if="canManage" label="审核" min-width="320"><template #default="{row}"><template v-if="row.status==='PENDING'"><el-input v-model="reasons[row.id]" :aria-label="`提现${row.id}审核说明`" maxlength="500" placeholder="驳回须填写原因" :disabled="!!busy"/><div class="toolbar"><el-button :disabled="!!busy" @click="review(row as DiningWithdrawal,'approve')">通过</el-button><el-button :disabled="!!busy" @click="review(row as DiningWithdrawal,'reject')">驳回</el-button></div></template></template></el-table-column></el-table><h2 style="margin-top:32px">佣金明细</h2><el-table :data="detail.incomes" empty-text="暂无佣金记录"><el-table-column prop="orderNo" label="订单" min-width="180"/><el-table-column prop="tableNumber" label="桌号" width="90"/><el-table-column label="佣金" width="120"><template #default="{row}">{{money(row.commissionFen)}}</template></el-table-column><el-table-column label="状态" min-width="150"><template #default="{row}">{{incomeLabel(row.status)}}</template></el-table-column><el-table-column prop="reason" label="说明" min-width="220"/><el-table-column prop="availableAt" label="可提现时间" min-width="190"/></el-table><p class="muted">展示最近100条佣金与提现记录，余额由服务器完整计算。</p></template></section></section></template>
